SELECT city, region_group, city_list, avg_sqft FROM (SELECT city, CASE WHEN region IN ('West', 'South') THEN 'group_a' ELSE 'other' END AS region_group, SORT_ARRAY(COLLECT_SET(city)) AS city_list, ROUND(AVG(sqft), 2) AS avg_sqft FROM stores WHERE region IN ('East', 'North', 'West') GROUP BY city, CASE WHEN region IN ('West', 'South') THEN 'group_a' ELSE 'other' END) AS x WHERE avg_sqft > 31 ORDER BY region_group;
